from itertools import product

# Partitions are decreasing tuples of positive integers; () is empty.
def norm(part):
    return tuple(x for x in part if x)

def contained(lam, mu):
    L = max(len(lam), len(mu))
    return all((lam[k] if k < len(lam) else 0) <= (mu[k] if k < len(mu) else 0)
               for k in range(L))

def partitions_of(n, max_part=None):
    if n == 0:
        yield ()
        return
    if max_part is None or max_part > n:
        max_part = n
    for first in range(max_part, 0, -1):
        for tail in partitions_of(n-first, first):
            yield (first,) + tail

def in_box(mu, q, r):
    return len(mu) <= r and (not mu or mu[0] <= q)

def horizontal_strip(lam, mu):
    # mu/lam has at most one square in each column iff its conjugate
    # coordinate differences are all 0 or 1.
    if not contained(lam, mu):
        return False
    width = max((lam[0] if lam else 0), (mu[0] if mu else 0))
    for col in range(1, width+1):
        a = sum(x >= col for x in lam)
        b = sum(x >= col for x in mu)
        if b-a not in (0, 1):
            return False
    return True

def pieri(lam, k, q, r):
    return {mu for mu in partitions_of(sum(lam)+k)
            if in_box(mu, q, r) and horizontal_strip(lam, mu)}

def slot_parts(i, j, p, c):
    q, r = i+p, j+c
    gamma = (i+2,) + (i,)*(j-1) if p >= 2 else None
    theta = (i,)*j + (1, 1) if c >= 2 else None
    return {
        'x0': (i,)*j,
        'x1': (i+1,) + (i,)*(j-1),
        'y1': (i,)*j + (1,),
        'gamma': gamma,
        'x2': (i+1, i+1) + (i,)*(j-2),
        'z': (i+1,) + (i,)*(j-1) + (1,),
        'y2': (i,)*j + (2,),
        'theta': theta,
        'q': q, 'r': r,
    }

def nonnull(*parts):
    return {x for x in parts if x is not None}

identity_checks = 0
matrix_checks = 0
tuples_checked = 0
for i, j in product(range(2, 7), repeat=2):
    for p, c in product(range(1, 6), repeat=2):
        if min(p, c) != 1:
            continue
        S = slot_parts(i, j, p, c)
        q, r = S['q'], S['r']
        claimed = [
            ('h1*x0', pieri(S['x0'], 1, q, r), nonnull(S['x1'], S['y1'])),
            ('h2*x0', pieri(S['x0'], 2, q, r), nonnull(S['gamma'], S['z'], S['y2'])),
            ('h1*x1', pieri(S['x1'], 1, q, r), nonnull(S['gamma'], S['x2'], S['z'])),
            ('h1*y1', pieri(S['y1'], 1, q, r), nonnull(S['z'], S['y2'], S['theta'])),
        ]
        for name, actual, expected in claimed:
            assert actual == expected, (i, j, p, c, name, actual, expected)
            identity_checks += 1
        # Coefficient rows in conditional named-column order, obtained from
        # the independently enumerated Pieri output rather than hard-coded rows.
        columns = [name for name in ('gamma','x2','z','y2','theta') if S[name] is not None]
        rows = []
        for lam, k in ((S['x0'],2), (S['x1'],1), (S['y1'],1)):
            actual = pieri(lam, k, q, r)
            rows.append([int(S[name] in actual) for name in columns])
        if p == 1 and c == 1:
            assert columns == ['x2','z','y2'], (columns,)
            assert rows == [[0,1,1],[1,1,0],[0,1,1]], rows
            minor = [[rows[a][b] for b in (1,2)] for a in (1,2)]
            det = minor[0][0]*minor[1][1] - minor[0][1]*minor[1][0]
            assert minor == [[1,1],[1,0]] and det == -1, (minor, det)
        matrix_checks += 1
        tuples_checked += 1

print('INPUT_I_J: 2..6')
print('INPUT_P_C: 1..5, min(p,c)=1')
print('PARAMETER_TUPLES:', tuples_checked)
print('PIERI_IDENTITIES_CHECKED:', identity_checks)
print('BOUNDARY_MATRIX_CHECKS:', matrix_checks)
print('DOUBLY_BOUNDARY_MATRIX: [[0, 1, 1], [1, 1, 0], [0, 1, 1]]')
print('DOUBLY_BOUNDARY_MINOR: [[1, 1], [1, 0]]')
print('DOUBLY_BOUNDARY_MINOR_DETERMINANT: -1')
print('RESULT: PASS')
